CREATE TABLE company (id BIGINT PRIMARY KEY, name VARCHAR(160) NOT NULL, system_name VARCHAR(80) NOT NULL, theme_color VARCHAR(20) NOT NULL);
CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(50) NOT NULL, permissions TEXT NOT NULL, menus TEXT NOT NULL);
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(60) NOT NULL, role_id BIGINT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at TIMESTAMP NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE dictionaries (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, category VARCHAR(40) NOT NULL, label VARCHAR(80) NOT NULL, value VARCHAR(50) NOT NULL, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE projects (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, owner VARCHAR(160) NOT NULL, contractor VARCHAR(160) NOT NULL, manager_id BIGINT NOT NULL, location VARCHAR(200), type VARCHAR(60), contract_amount DECIMAL(20,2) NOT NULL, budget_amount DECIMAL(20,2) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, progress DECIMAL(5,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(manager_id) REFERENCES users(id));
CREATE TABLE project_progress (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, project_id BIGINT NOT NULL, progress DECIMAL(5,2) NOT NULL, note VARCHAR(500), operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE suppliers (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, contact VARCHAR(80), phone VARCHAR(50), category VARCHAR(60), status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', qualification VARCHAR(500), qualification_expiry DATE, rating DECIMAL(3,1) NOT NULL DEFAULT 4.5);
CREATE TABLE materials (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, specification VARCHAR(160), unit VARCHAR(20) NOT NULL, category VARCHAR(60) NOT NULL, safety_stock DECIMAL(18,3) NOT NULL DEFAULT 0, reference_price DECIMAL(18,4) NOT NULL DEFAULT 0);
CREATE TABLE warehouses (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, location VARCHAR(160));
CREATE TABLE purchase_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(60) NOT NULL UNIQUE, project_id BIGINT NOT NULL, applicant_id BIGINT NOT NULL, required_date DATE NOT NULL, note VARCHAR(1000), status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', total_amount DECIMAL(20,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(applicant_id) REFERENCES users(id));
CREATE TABLE request_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, request_id BIGINT NOT NULL, material_id BIGINT NOT NULL, quantity DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,4) NOT NULL, amount DECIMAL(20,2) NOT NULL, UNIQUE(request_id, material_id), FOREIGN KEY(request_id) REFERENCES purchase_requests(id), FOREIGN KEY(material_id) REFERENCES materials(id));
CREATE TABLE approvals (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, request_id BIGINT NOT NULL, operator_id BIGINT NOT NULL, decision VARCHAR(30) NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES purchase_requests(id));
CREATE TABLE quotes (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, request_id BIGINT NOT NULL, supplier_id BIGINT NOT NULL, delivery_days INT NOT NULL, valid_until DATE NOT NULL, note VARCHAR(1000), total_amount DECIMAL(20,2) NOT NULL, selected BOOLEAN NOT NULL DEFAULT FALSE, selection_reason VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(request_id) REFERENCES purchase_requests(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE quote_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, quote_id BIGINT NOT NULL, request_item_id BIGINT NOT NULL, unit_price DECIMAL(18,4) NOT NULL, amount DECIMAL(20,2) NOT NULL, UNIQUE(quote_id,request_item_id), FOREIGN KEY(quote_id) REFERENCES quotes(id), FOREIGN KEY(request_item_id) REFERENCES request_items(id));
CREATE TABLE purchase_orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(60) NOT NULL UNIQUE, project_id BIGINT NOT NULL, request_id BIGINT NOT NULL UNIQUE, quote_id BIGINT NOT NULL, supplier_id BIGINT NOT NULL, total_amount DECIMAL(20,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', buyer_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(request_id) REFERENCES purchase_requests(id), FOREIGN KEY(quote_id) REFERENCES quotes(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id));
CREATE TABLE order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, order_id BIGINT NOT NULL, material_id BIGINT NOT NULL, request_item_id BIGINT NOT NULL, quantity DECIMAL(18,3) NOT NULL, received_quantity DECIMAL(18,3) NOT NULL DEFAULT 0, unit_price DECIMAL(18,4) NOT NULL, amount DECIMAL(20,2) NOT NULL, UNIQUE(order_id,material_id), FOREIGN KEY(order_id) REFERENCES purchase_orders(id), FOREIGN KEY(material_id) REFERENCES materials(id));
CREATE TABLE receipts (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(60) NOT NULL UNIQUE, order_id BIGINT NOT NULL, project_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, reference VARCHAR(100) NOT NULL UNIQUE, note VARCHAR(1000), amount DECIMAL(20,2) NOT NULL, operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES purchase_orders(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id));
CREATE TABLE receipt_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, receipt_id BIGINT NOT NULL, order_item_id BIGINT NOT NULL, material_id BIGINT NOT NULL, quantity DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,4) NOT NULL, amount DECIMAL(20,2) NOT NULL, FOREIGN KEY(receipt_id) REFERENCES receipts(id));
CREATE TABLE inventory (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, warehouse_id BIGINT NOT NULL, material_id BIGINT NOT NULL, quantity DECIMAL(18,3) NOT NULL DEFAULT 0, average_price DECIMAL(18,6) NOT NULL DEFAULT 0, stock_value DECIMAL(20,2) NOT NULL DEFAULT 0, UNIQUE(tenant_id,warehouse_id,material_id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(material_id) REFERENCES materials(id));
CREATE TABLE issues (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(60) NOT NULL UNIQUE, project_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, reference VARCHAR(100) NOT NULL UNIQUE, note VARCHAR(1000), amount DECIMAL(20,2) NOT NULL, operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id));
CREATE TABLE stock_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, warehouse_id BIGINT NOT NULL, material_id BIGINT NOT NULL, project_id BIGINT NOT NULL, kind VARCHAR(20) NOT NULL, quantity DECIMAL(18,3) NOT NULL, unit_cost DECIMAL(18,6) NOT NULL, amount DECIMAL(20,2) NOT NULL, reference VARCHAR(100) NOT NULL, receipt_id BIGINT, issue_id BIGINT, operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(material_id) REFERENCES materials(id));
CREATE TABLE costs (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, project_id BIGINT NOT NULL, category VARCHAR(30) NOT NULL, amount DECIMAL(20,2) NOT NULL, description VARCHAR(500) NOT NULL, incurred_date DATE NOT NULL, operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE contracts (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, type VARCHAR(30) NOT NULL, project_id BIGINT NOT NULL, supplier_id BIGINT, order_id BIGINT, amount DECIMAL(20,2) NOT NULL, signed_date DATE NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, status VARCHAR(30) NOT NULL, payment_plan TEXT, attachment_name VARCHAR(200), attachment_key VARCHAR(80), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), FOREIGN KEY(order_id) REFERENCES purchase_orders(id));
CREATE TABLE payables (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, order_id BIGINT NOT NULL UNIQUE, supplier_id BIGINT NOT NULL, project_id BIGINT NOT NULL, amount DECIMAL(20,2) NOT NULL DEFAULT 0, paid_amount DECIMAL(20,2) NOT NULL DEFAULT 0, FOREIGN KEY(order_id) REFERENCES purchase_orders(id));
CREATE TABLE payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, payable_id BIGINT NOT NULL, amount DECIMAL(20,2) NOT NULL, reference VARCHAR(100) NOT NULL UNIQUE, note VARCHAR(1000), operator_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payable_id) REFERENCES payables(id));
CREATE TABLE payment_applications (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, payable_id BIGINT NOT NULL, amount DECIMAL(20,2) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', note VARCHAR(1000), applicant_id BIGINT NOT NULL, payment_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(payable_id) REFERENCES payables(id), FOREIGN KEY(payment_id) REFERENCES payments(id));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT NOT NULL DEFAULT 1, operator_id BIGINT NOT NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id BIGINT, detail VARCHAR(2000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_requests_project ON purchase_requests(tenant_id,project_id,status);
CREATE INDEX idx_orders_project ON purchase_orders(tenant_id,project_id,status);
CREATE INDEX idx_movements_project ON stock_movements(tenant_id,project_id,kind);
CREATE INDEX idx_costs_project ON costs(tenant_id,project_id);
